<?php
require_once __DIR__.'/CustomerAccountAmount.class.php';
/** The same authorized projection supplies the UI, Excel and printable PDF view. */
class CustomerAccountExport
{
    public static function matrix(array $s)
    {
        $head=['ID','Date','Direction','Description','Reference','Original currency','Source amount (scoped for partial view)','Scoped original amount','USD per original unit','Rate date','Rate source','Scoped signed USD','Running USD','Allocation rounding cents','Reversal of'];
        foreach($s['columns'] as $c)$head[]=$c['label'];$rows=[$head];
        foreach($s['rows'] as $r){$p=$r['payload'];$signed=$p['direction']==='received'?$r['scoped_base_minor']:bcsub('0',$r['scoped_base_minor'],0);$row=[(string)$r['id'],$p['date'],$p['direction'],$p['description'],$p['reference'],$p['currency'],$p['amount'],CustomerAccountAmount::money($r['scoped_original_minor']),$p['rate'],$p['rate_date'],$p['rate_source'],CustomerAccountAmount::money($signed),CustomerAccountAmount::money($r['running_minor']),$r['rounding_minor'],(string)$r['reversal_of']];foreach($s['columns'] as $c)$row[]=$p['custom'][(string)$c['rowid']]??'';$rows[]=$row;}
        $rows[]=[];$rows[]=['Customer',$s['customer']['nom'],'Project',(string)$s['project'],'Card',(string)$s['task']];$rows[]=['Posted cash balance USD',CustomerAccountAmount::money($s['balance_minor']),'Unallocated USD',CustomerAccountAmount::money($s['unallocated_minor'])];$rows[]=['Due USD — funds needed to cover recorded spending',CustomerAccountAmount::money(bccomp($s['balance_minor'],'0',0)<0?bcsub('0',$s['balance_minor'],0):'0')];foreach($s['original_balances'] as $currency=>$minor)$rows[]=['Original currency position',$currency,'Balance',CustomerAccountAmount::money($minor),'Due',CustomerAccountAmount::money(bccomp($minor,'0',0)<0?bcsub('0',$minor,0):'0')];$rows[]=['Manual operational ledger. Drafts excluded. Not native accounting, revenue or unpaid obligations.'];$rows[]=['Values exceeding Excel numeric precision are exported as exact decimal text.'];$rows[]=['Allocation breakdown — already included in the transaction totals above; do not add again.'];$rows[]=['Entry ID','Project ID (0 unallocated)','Card ID (0 project only)','Original amount','Currency','Base USD','Rounding cents'];foreach($s['rows'] as $r)foreach($r['allocations'] as $l)$rows[]=[(string)$r['id'],(string)($l['project']??0),(string)($l['task']??0),CustomerAccountAmount::money($l['original_minor']),$r['payload']['currency'],CustomerAccountAmount::money($l['base_minor']),(string)$l['rounding_minor']];$rows[]=['FX direction: USD per 1 original currency unit; half-up per entry; last allocation carries rounding residual.'];return $rows;
    }
    public static function xlsx(array $s)
    {
        if(!class_exists('ZipArchive'))throw new RuntimeException('ZipArchive is required for XLSX.');
        $xml='<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';
        foreach(self::matrix($s) as $i=>$row){$xml.='<row r="'.($i+1).'">';foreach($row as $j=>$v){$n=$j+1;$col='';while($n){$col=chr(65+(($n-1)%26)).$col;$n=(int)(($n-1)/26);}$cell=$col.($i+1);$v=htmlspecialchars((string)$v,ENT_XML1|ENT_QUOTES,'UTF-8');$numeric=$i>0&&$i<=count($s['rows'])&&in_array($j,[6,7,8,11,12,13],true)&&strlen(ltrim(preg_replace('/[^0-9]/','',(string)$row[$j]),'0'))<=15;$xml.=$numeric?'<c r="'.$cell.'"><v>'.$v.'</v></c>':'<c r="'.$cell.'" t="inlineStr"><is><t xml:space="preserve">'.$v.'</t></is></c>';}$xml.='</row>';}$xml.='</sheetData></worksheet>';
        $files=['[Content_Types].xml'=>'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>', '_rels/.rels'=>'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>', 'xl/workbook.xml'=>'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Account statement" sheetId="1" r:id="rId1"/></sheets></workbook>', 'xl/_rels/workbook.xml.rels'=>'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>', 'xl/worksheets/sheet1.xml'=>$xml];
        $tmp=tempnam(sys_get_temp_dir(),'cpo-account-');try{$z=new ZipArchive();if($z->open($tmp,ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Export unavailable.');foreach($files as $name=>$bytes)$z->addFromString($name,$bytes);$z->close();return file_get_contents($tmp);}finally{unlink($tmp);}
    }
}
